<?php
namespace App\Http\Controllers;

use App\Services\{ContactImport,ContactImportCache,ContactFiles,MailContacts,SalonStore,StaffAccess,Tenant};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Crypt,Http};
use Illuminate\Support\Str;

final class ContactImportController
{
    private function owner(Request $r):int
    {
        abort_unless($r->session()->get('admin')===true&&!StaffAccess::editor($r),403);
        return (int)$r->session()->get('provider_id',1);
    }
    private function key(Request $r,string $id):string{$nonce=$r->session()->get('contact_import_nonce');if(!is_string($nonce)){$nonce=bin2hex(random_bytes(32));$r->session()->put('contact_import_nonce',$nonce);}return 'contact-import:'.$this->owner($r).':'.hash('sha256',$nonce).':'.$id;}
    private function stage(Request $r,array $data):string{$id=(string)Str::uuid();ContactImportCache::store()->put($this->key($r,$id),Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),1200);return $id;}
    private function readStage(Request $r,string $id):array{$raw=ContactImportCache::store()->get($this->key($r,$id));abort_unless($raw,410,'Az import előnézete lejárt. Olvasd be újra a névjegyeket.');return json_decode(Crypt::decryptString($raw),true,512,JSON_THROW_ON_ERROR);}
    public function status(Request $r){$this->owner($r);$s=app(SalonStore::class)->read();$configured=[];foreach(['google','microsoft'] as $engine){$c=MailContacts::credentials($engine);$configured[$engine]=!empty($c['id'])&&!empty($c['secret']);}return response()->json(['prompts'=>$s['contactImport']??[],'configured'=>$configured])->header('Cache-Control','no-store');}
    public function dismiss(Request $r){$this->owner($r);$v=$r->validate(['source'=>'required|in:phone,mail']);app(SalonStore::class)->mutate(function(&$s)use($v){$s['contactImport'][$v['source']]['snoozedUntil']=now()->addDays(7)->toIso8601String();},false);return response()->json(['ok'=>true]);}
    public function file(Request $r){$this->owner($r);$r->validate(['file'=>'required|file|max:5120']);return response()->json(ContactFiles::read($r->file('file')))->header('Cache-Control','no-store');}
    public function preview(Request $r){$this->owner($r);$v=$r->validate(['source'=>'required|in:phone,mail,file','records'=>'required|array|min:1|max:2000','records.*'=>'required|array','records.*.name'=>'nullable|string|max:2000','records.*.phone'=>'nullable|string|max:2000','records.*.email'=>'nullable|string|max:2000']);$records=array_map(fn($row)=>array_intersect_key($row,array_flip(['name','phone','email'])),$v['records']);$items=ContactImport::preview(app(SalonStore::class)->read()['clients'],$records);$id=$this->stage($r,['type'=>'preview','items'=>$items,'source'=>$v['source']]);return response()->json(['id'=>$id,'items'=>$items])->header('Cache-Control','no-store');}
    public function commit(Request $r){$this->owner($r);$v=$r->validate(['id'=>'required|uuid','selected'=>'required|array|min:1|max:2000','selected.*'=>'required|integer|min:0|max:1999|distinct']);$key=$this->key($r,$v['id']);$result=ContactImportCache::store()->lock($key.':lock',30)->block(3,function()use($r,$v,$key){$data=$this->readStage($r,$v['id']);if(isset($data['result']))return $data['result'];abort_unless(($data['type']??'')==='preview',422);$result=app(SalonStore::class)->mutate(function(&$s)use($data,$v){$result=ContactImport::apply($s,$data['items'],$v['selected']);if($result['added']+$result['updated']>0){$s['contactImport'][$data['source']]['doneAt']=now()->toIso8601String();}return $result;},false);ContactImportCache::store()->put($key,Crypt::encryptString(json_encode(['result'=>$result])),1200);return $result;});return response()->json($result);}
    public function remote(Request $r,string $id){$this->owner($r);$data=$this->readStage($r,$id);abort_unless(($data['type']??'')==='remote',404);return response()->json(['records'=>$data['records'],'source'=>'mail'])->header('Cache-Control','no-store');}
    public function start(Request $r,string $engine){$owner=$this->owner($r);$c=MailContacts::credentials($engine);abort_unless($c['id']&&$c['secret'],503,'A központi névjegykapcsolat még nincs beállítva. Válassz CSV vagy VCF névjegyfájlt.');$state=bin2hex(random_bytes(32));$verifier=bin2hex(random_bytes(32));$r->session()->put('contacts_oauth',['state'=>$state,'verifier'=>$verifier,'engine'=>$engine,'owner'=>$owner,'expires'=>time()+600]);$uri=rtrim(config('app.url'),'/').'/auth/contact-import/'.$engine.'/callback';$url=$engine==='google'?'https://accounts.google.com/o/oauth2/v2/auth':'https://login.microsoftonline.com/common/oauth2/v2.0/authorize';$scope=$engine==='google'?'https://www.googleapis.com/auth/contacts.readonly':'https://graph.microsoft.com/Contacts.Read';return redirect()->away($url.'?'.http_build_query(['client_id'=>$c['id'],'redirect_uri'=>$uri,'response_type'=>'code','scope'=>$scope,'state'=>$state,'code_challenge'=>rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='),'code_challenge_method'=>'S256','prompt'=>'consent']));}
    public function callback(Request $r,string $engine){$owner=$this->owner($r);$saved=$r->session()->pull('contacts_oauth');$target='/?provider='.$owner.'&contactImport=';if(!$saved||$saved['expires']<time()||$saved['owner']!==$owner||$saved['engine']!==$engine||!is_string($r->query('state'))||!hash_equals($saved['state'],$r->query('state'))||!$r->filled('code'))return redirect($target.'error');app(Tenant::class)->id=$owner;
        try{$c=MailContacts::credentials($engine);$url=$engine==='google'?'https://oauth2.googleapis.com/token':'https://login.microsoftonline.com/common/oauth2/v2.0/token';$response=Http::timeout(15)->asForm()->post($url,['client_id'=>$c['id'],'client_secret'=>$c['secret'],'grant_type'=>'authorization_code','code'=>$r->query('code'),'redirect_uri'=>rtrim(config('app.url'),'/').'/auth/contact-import/'.$engine.'/callback','code_verifier'=>$saved['verifier']]);if(!$response->successful())return redirect($target.'error');$token=$response->json('access_token');if(!is_string($token)||$token==='')return redirect($target.'error');$records=MailContacts::read($engine,$token);$id=$this->stage($r,['type'=>'remote','records'=>$records]);return redirect($target.$id);
        }catch(\Throwable){return redirect($target.'error');}
    }
}
